                this.allLoadedChunks = stats.values().stream().reduce(Integer::sum).orElse(0);
                this.allLoadedWorlds = stats.keySet().size();
                this.allWorlds = statistics.getChunks().size();
                this.allChunks = 0;
                for (Map.Entry entry : statistics.getChunks().entrySet()) {
